const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=(x,y,s,n=17)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f4ed" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const line=(d,c='#bcd0ce',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const ball=(x,y,r,c)=>`<ellipse cx="${x+3}" cy="${y+r}" rx="${r}" ry="${r*.3}" fill="#102632" opacity=".5"/><circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#eadbc1" stroke-width="1.3"/><circle cx="${x-r*.28}" cy="${y-r*.32}" r="${r*.24}" fill="#fff8e6" opacity=".5"/>`;
export const evoSVG=(a,label)=>`<svg viewBox="0 0 560 420" role="img" aria-label="${esc(label)}">${a}</svg>`;
export function cohortFigure({counts={light:10,dark:10},habitat='dark',generation=0,caption=''}={}){let a=tx(280,30,'Inherited variants across generations',23)+tx(280,70,'Habitat: '+habitat+' · generation '+generation,18);a+=`<rect x="30" y="94" width="500" height="214" rx="23" fill="${habitat==='dark'?'#284139':'#b9a98b'}" stroke="#adc3b9"/>`;for(let i=0;i<counts.light+counts.dark;i++){let dark=i>=counts.light,x=75+i%10*45,y=150+Math.floor(i/10)*100;a+=ball(x,y,15,dark?'#42666a':'#dfbd8d')+tx(x,y+39,dark?'D':'L',13);}a+=tx(280,342,'L: '+counts.light+' · D: '+counts.dark+' · total: '+(counts.light+counts.dark),19)+tx(280,380,caption||'Different contributions to offspring; not individuals recolouring',14)+tx(280,406,'Deterministic classroom cohorts · not a wild-population forecast',12);return evoSVG(a,'Original illustrative cohort: '+counts.light+' light L and '+counts.dark+' dark D, habitat '+habitat+', generation '+generation+'. Individuals keep their variant; population proportions change.');}
export function selectionFilmFigure(p){let phase=Math.min(3,Math.floor(Math.max(0,Math.min(1,p))*4)),counts=[{light:10,dark:10},{light:5,dark:10},{light:7,dark:13},{light:4,dark:16}][phase];return cohortFigure({counts,generation:phase<2?0:phase-1,caption:['Existing inherited variation','Illustrative survivors: fewer conspicuous light individuals','Offspring replenish the fixed20 cohort','Selection and reproduction repeat'][phase]});}
export function breedingFigure({progress=.5}={}){let p=Math.max(0,Math.min(1,progress)),phase=Math.min(3,Math.floor(p*4)),a=tx(280,30,'Artificial selection repeats over generations',22);let rows=[[2,4,6,8],[4,5,7,8],[5,7,8,8]];for(let j=0;j<3;j++){let yy=110+j*90;a+=tx(65,yy+5,'Gen '+j,15);for(let k=0;k<4;k++){let x=175+k*90,v=rows[j][k];a+=ball(x,yy,12+v*.9,j<phase&&k>=2?'#e5b28f':'#a9c2b4')+tx(x,yy+38,String(v),15);if(j<2&&k>=2)a+=line(`M${x} ${yy+44}v16`,'#dcb998',1.5);}}a+=tx(280,400,'Toy inherited trait scores · selected parents are highlighted',14);return evoSVG(a,'Toy selective-breeding generations with variable trait scores; humans select parents/offspring repeatedly. Scores are not real trait measurements or guarantees.');}
export function transferFigure({progress=.5}={}){let p=Math.max(0,Math.min(1,progress)),phase=Math.min(3,Math.floor(p*4)),a=tx(280,30,'Track the marked gene through a vector',22);a+=line('M45 105h150','#b2c9cb',13)+line('M90 105h48','#edb08d',15)+tx(120,155,'Donor DNA',17);a+=`<circle cx="280" cy="105" r="43" fill="none" stroke="#a9c8ba" stroke-width="8"/>`+tx(280,177,'Vector plasmid',16);a+=`<ellipse cx="420" cy="280" rx="95" ry="70" fill="#36596b" stroke="#b3cecb" stroke-width="3"/>`+tx(420,378,'Recipient cell',17);let x=phase===0?110:phase===1?280:phase===2?280+(p*4-2)*140:420,y=phase<2?105:phase===2?105+(p*4-2)*175:280;a+=line(`M${x-18} ${y}h36`,'#efb08c',10);if(phase>=2)a+=`<circle cx="420" cy="280" r="35" fill="none" stroke="#aac6b8" stroke-width="6"/>`;a+=tx(280,205,['Enzymes isolate gene','Gene inserted into vector','Vector transfers gene into cells','Early introduction and gene expression'][phase],16)+tx(280,412,'Gene / carrier / cell / product are distinct · symbolic scale',13);return evoSVG(a,'Gene-transfer conceptual stage '+(phase+1)+'. Marked gene from donor DNA is inserted into plasmid vector and transferred into recipient cells. Not a laboratory protocol.');}
export function traitFigure(){let a=tx(280,30,'Original illustrative plant heights / cm',22);let rows=[['Genotype','Dim','Bright'],['G1','10','16'],['G2','14','22']];for(let i=0;i<3;i++)for(let j=0;j<3;j++)a+=tx(105+j*175,110+i*75,rows[i][j],21);a+=tx(280,357,'Compare one factor while holding the other constant',16)+tx(280,402,'Fictional data illustrate gene–environment interaction',14);return evoSVG(a,'Fictional plant height table in cm: G1 dim10 bright16; G2 dim14 bright22. Gene and environment interactions affect phenotype.');}
export function evidenceFigure({kind='variation',state=''}={}){let rows=kind==='variation'||kind==='mutation'?['Inherited information and environment affect phenotype','Mutation creates new variants; reproduction reshuffles','Most variants have no effect on phenotype']:kind==='breeding-goals'?['Crops: disease resistance','Farm animals: meat or milk · dogs: gentle nature','Flowers: large or unusual appearance']:kind==='breeding-evidence'?['Benefits: useful inherited characteristics','Risks: reduced diversity and inherited defects','Evaluate productivity, welfare and ethical concerns']:kind==='engineering-uses'?['Transferred gene → desired characteristic','Crops: disease, insect or herbicide resistance','Bacteria produce insulin → harvest and purify']:kind==='transfer-evidence'?['Gene: DNA carrying information','Vector: plasmid or virus carrying the gene','Expression produces an effect; success not guaranteed']:['Fictional plot yields:40 → 50 units','Potential benefits depend on conditions','Investigate wildflower/insect impacts and uncertainty'];return evoSVG(tx(280,35,'Compare the evidence and its limits',22)+rows.map((s,i)=>tx(280,130+i*85,s,17)).join('')+tx(280,407,'Original educational comparison · use the supplied context',13),'Evidence comparison. '+rows.join('. '));}
export function evoFigure(o={}){if(o.concealed)return evoSVG(tx(280,210,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');if(o.kind==='trait-data')return traitFigure();if(o.kind==='selection')return selectionFilmFigure(o.progress??.5);if(o.kind==='selection-data')return cohortFigure(o);if(o.kind==='breeding')return breedingFigure(o);if(o.kind==='transfer')return transferFigure(o);return evidenceFigure(o);}
